def cloud(cx, cy, w, main, hi, sh):
    # flat-bottom pixel cloud from overlapping discs
    blobs = [(-w//2, 1, w//4, 3), (-w//4, -2, w//3, 4), (w//6, -1, w//3, 4), (w//2-2, 1, w//4, 3)]
    for dx, dy, rx, ry in blobs:
        disc(cx+dx, cy+dy, max(rx,2), max(ry,2), main)
    rect(cx-w//2, cy, cx+w//2, cy+2, main)
    # shadow underside
    for x in range(cx-w//2+1, cx+w//2):
        px(x, cy+3, sh)
        if (x+cy) % 3: px(x, cy+2, sh)
    # highlight top
    for dx, dy, rx, ry in blobs:
        for x in range(cx+dx-rx+2, cx+dx+rx-1):
            px(x, cy+dy-ry, hi)

