def cloud(cx, cy, w, main, hi, sh):
    # puffy cloud: scalloped discs, shadow copy dropped 2px, short top highlights
    u = max(3, w // 10)
    blobs = [(-4*u, 1, 2*u, u), (-2*u, -u, 3*u, u+2), (u, -u-1, 3*u, u+2),
             (3*u, 0, 2*u, u+1), (0, 2, 3*u, u)]
    for dx, dy, rx, ry in blobs:
        disc(cx+dx, cy+dy+2, rx, ry, sh)
    for dx, dy, rx, ry in blobs:
        disc(cx+dx, cy+dy, rx, ry, main)
